FileOutputStream outFile = new FileOutputStream("CandidateNames.txt");
String data = "Ahalya Bhairav Chitra Dushyant Eshwari Falgun Gargi Hiren";
byte[] bArray = data.getBytes();
outFile.write(bArray);
outFile.close();

FileInputStream inFile = new FileInputStream("CandidateNames.txt");
int i = inFile.read();
while (i != -1) {
    System.out.print((char) i);
    i = inFile.read();
}
inFile.close();

BufferedReader inFile = new BufferedReader(new FileReader("ReadFrom.txt"));
BufferedWriter outFile = new BufferedWriter(new FileWriter("WriteTo.txt"));
int i = inFile.read();
while(i != -1) {
    outFile.write(i);
    i = inFile.read();
}
inFile.close();
outFile.close();

